import csv,collections,numpy as np
r=list(csv.DictReader(open('responses.csv')))
pid=-1;P=[]
for x in r:
  if x['trial_index']=='0': pid+=1
  P.append(pid)
d=collections.defaultdict(dict)
for x,p in zip(r,P): d[(x['number_set'],x['target'])][p]=int(x['rating'])
for p in range(10):
  a=[];
  for k,v in d.items():
    if p in v and len(v)>=5:
      others=[v[q] for q in v if q!=p]; a.append((v[p], np.mean(others)))
  a=np.array(a); print(p, len(a), round(np.corrcoef(a[:,0],a[:,1])[0,1],3))
"

